/** Records who the workspace's owner is. */
export async function setOrgOwner(
  orgId: OrgId,
  ownerId: UserId,
): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set({ ownerId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** The workspace's `pending` handover row (it may have lapsed), if any. */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

export async function insertHandover(input: {
  orgId: OrgId;
  fromUserId: UserId;
  toUserId: UserId;
  createdAt: IsoTimestamp;
  expiresAt: IsoTimestamp;
}): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({ id: newId(), ...input, status: "pending", resolvedAt: null })
    .returning()
    .get();
  return toOwnershipHandover(row);
}

/** Moves a handover out of `pending`; a no-op row-wise if it already left. */
export async function resolveHandover(
  handoverId: string,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Pending handover ${handoverId} not found`);
  return toOwnershipHandover(row);
}

/** Withdraws the open handover if `userId` is on either side of it. */
export async function cancelPendingHandoverInvolving(
  orgId: OrgId,
  userId: UserId,
  resolvedAt: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
