function hasLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= new Date(handover.expiresAt).getTime();
}

/** Only the recorded owner may offer or withdraw; the owner role is not enough. */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.userId === org.ownerId) return;
  throw new PermissionDeniedError("org:update", {
    action: "org:update",
    resourceKind: "organization",
    allowed: false,
    reason: "denied_by_role",
  });
}

/** The open (pending, not lapsed) offer for the workspace, if any. */
async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await orgRepo.findPendingHandover(orgId);
  return pending && !hasLapsed(pending, now) ? pending : null;
}

/**
 * The offer the actor may accept or decline: it must be pending and addressed
 * to them, and it must not have lapsed.
 */
async function requireOfferedToActor(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const pending = await orgRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, new Date())) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

/** The recorded owner offers the workspace to another active member. */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const pending = await orgRepo.findPendingHandover(orgId);
  if (pending) {
    if (!hasLapsed(pending, now)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    await orgRepo.resolveHandover(
      pending.id,
      "expired",
      toIsoTimestamp(new Date(pending.expiresAt)),
    );
  }

  const handover = await orgRepo.insertHandover({
    orgId,
    fromUserId: org.ownerId,
    toUserId,
    createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of this workspace",
    body: `${org.name} can be handed over to you; accept to become its owner`,
    href: "/settings/general",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over. The new owner is promoted
 * before the old one steps down, so the workspace always has an owner and the
 * last-owner rule never comes into play.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const handover = await requireOfferedToActor(actor, orgId);

  const incoming = await memberRepo.findMember(orgId, handover.toUserId);
  if (!incoming || incoming.status !== "active") {
    throw new OwnershipHandoverError("nothing_pending");
  }
  const outgoing = await memberRepo.findMember(orgId, handover.fromUserId);

  await orgRepo.resolveHandover(
    handover.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );
  const org = await orgRepo.setOrgOwner(orgId, handover.toUserId);

  const roleChanges: { memberId: Member["id"]; from: Role; to: Role }[] = [];

  if (incoming.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    roleChanges.push({ memberId: incoming.id, from: incoming.role, to: "owner" });
  }
  if (outgoing && outgoing.role === "owner") {
    await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    roleChanges.push({ memberId: outgoing.id, from: "owner", to: "admin" });
  }

  for (const change of roleChanges) {
    await emit("member.role_changed", { ...actorEnvelope(actor), ...change });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: handover.toUserId,
  });

  return org;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const handover = await requireOfferedToActor(actor, orgId);
  return orgRepo.resolveHandover(
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The offering owner withdraws an open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const now = new Date();
  const open = await findOpenHandover(orgId, now);
  if (!open) throw new OwnershipHandoverError("nothing_pending");

  return orgRepo.resolveHandover(open.id, "canceled", toIsoTimestamp(now));
}

/** Any member can see whether an offer is open and to whom. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return findOpenHandover(orgId, new Date());
}
