  const org = await orgRepo.setOrgOwner(orgId, handover.toUserId);

  const roleChanges: { memberId: Member["id"]; from: Role; to: Role }[] = [];

  if (incoming.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    roleChanges.push({ memberId: incoming.id, from: incoming.role, to: "owner" });
  }
  if (outgoing && outgoing.role === "owner") {
    await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    roleChanges.push({ memberId: outgoing.id, from: "owner", to: "admin" });
  }

  for (const change of roleChanges) {
    await emit("member.role_changed", { ...actorEnvelope(actor), ...change });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: handover.toUserId,
  });

  return org;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const handover = await requireOfferedToActor(actor, orgId);
  return orgRepo.resolveHandover(
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The offering owner withdraws an open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const now = new Date();
  const open = await findOpenHandover(orgId, now);
  if (!open) throw new OwnershipHandoverError("nothing_pending");

  return orgRepo.resolveHandover(open.id, "canceled", toIsoTimestamp(now));
}

/** Any member can see whether an offer is open and to whom. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return findOpenHandover(orgId, new Date());
}
