/**
 * Ownership handover: offer, accept, decline, withdraw, lapse.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as billingService from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { subscribe } from "@/lib/event-bus";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const offs: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => cleanup());

afterEach(() => {
  vi.useRealTimers();
  for (const off of offs.splice(0)) off();
});

async function refusal(promise: Promise<unknown>): Promise<string> {
  const error = await promise.then(
    () => null,
    (e: unknown) => e,
  );
  expect(error).toBeInstanceOf(OwnershipHandoverError);
  return (error as OwnershipHandoverError).reason;
}

describe("ownership handover", () => {
  it("offers, shows and accepts", async () => {
    const t = await createTenant("ho-accept");
    const seen: unknown[] = [];
    offs.push(
      subscribe("member.role_changed", (p) => void seen.push(["role", p.from, p.to, p.actorId])),
      subscribe("organization.ownership_transferred", (p) => void seen.push(["transfer", p.actorId])),
    );

    const offer = await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    expect(offer.status).toBe("pending");
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(7 * 86_400_000);
    expect((await orgService.getPendingOwnershipHandover(t.actors.viewer, t.org.id))?.toUserId).toBe(t.userIds.member);

    expect(await refusal(orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin))).toBe("pending_exists");
    expect(await refusal(orgService.acceptOwnershipHandover(t.actors.admin, t.org.id))).toBe("nothing_pending");

    const org = await orgService.acceptOwnershipHandover(t.actors.member, t.org.id);
    expect(org.ownerId).toBe(t.userIds.member);
    expect((await memberRepo.findMember(t.org.id, t.userIds.member))?.role).toBe("owner");
    expect((await memberRepo.findMember(t.org.id, t.userIds.owner))?.role).toBe("admin");
    expect(seen).toEqual([
      ["role", "member", "owner", t.userIds.member],
      ["role", "owner", "admin", t.userIds.member],
      ["transfer", t.userIds.member],
    ]);
    expect(await orgService.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).toBeNull();
    expect(await refusal(orgService.acceptOwnershipHandover(t.actors.member, t.org.id))).toBe("nothing_pending");

    await expect(
      billingService.changePlan(t.actors.owner, { orgId: t.org.id, plan: "growth", interval: "monthly" }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      billingService.getBillingSummary({ ...t.actors.member, role: "owner" }, t.org.id),
    ).resolves.toBeDefined();

    const previous = await memberRepo.findMember(t.org.id, t.userIds.owner);
    await memberService.removeMember(
      { ...t.actors.member, role: "owner" },
      { orgId: t.org.id, memberId: previous!.id },
    );
  });

  it("guards offers", async () => {
    const t = await createTenant("ho-guards");
    const other = await createTenant("ho-guards-other");
    await expect(orgService.initiateOwnershipHandover(t.actors.admin, t.org.id, t.userIds.member)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(orgService.cancelOwnershipHandover(t.actors.admin, t.org.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await refusal(orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.owner))).toBe("self");
    await expect(orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, other.userIds.member)).rejects.toBeInstanceOf(NotFoundError);
    await expect(orgService.getPendingOwnershipHandover(t.actors.owner, other.org.id)).rejects.toBeInstanceOf(TenantScopeError);
    expect(await refusal(orgService.cancelOwnershipHandover(t.actors.owner, t.org.id))).toBe("nothing_pending");

    // A co-owner who is not the recorded owner is refused.
    const co = await memberRepo.findMember(t.org.id, t.userIds.admin);
    await memberRepo.updateMemberRole(t.org.id, co!.id, "owner");
    await expect(
      orgService.initiateOwnershipHandover({ ...t.actors.admin, role: "owner" }, t.org.id, t.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("declines, withdraws and lapses", async () => {
    const t = await createTenant("ho-lapse");
    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin);
    const declined = await orgService.declineOwnershipHandover(t.actors.admin, t.org.id);
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).not.toBeNull();

    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin);
    expect((await orgService.cancelOwnershipHandover(t.actors.owner, t.org.id)).status).toBe("canceled");
    expect(await refusal(orgService.declineOwnershipHandover(t.actors.admin, t.org.id))).toBe("nothing_pending");

    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-05-01T10:00:00.000Z"));
    const offer = await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin);
    vi.setSystemTime(new Date(Date.parse(offer.expiresAt) - 1));
    expect(await orgService.getPendingOwnershipHandover(t.actors.owner, t.org.id)).not.toBeNull();
    vi.setSystemTime(new Date(offer.expiresAt));
    expect(await orgService.getPendingOwnershipHandover(t.actors.owner, t.org.id)).toBeNull();
    expect(await refusal(orgService.acceptOwnershipHandover(t.actors.admin, t.org.id))).toBe("expired");
    expect(await refusal(orgService.declineOwnershipHandover(t.actors.admin, t.org.id))).toBe("expired");
    const again = await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    expect(again.status).toBe("pending");
  });

  it("withdraws automatically when either side is removed", async () => {
    const t = await createTenant("ho-remove");
    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    const target = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: target!.id });
    expect(await orgRepo.findPendingHandover(t.org.id)).toBeNull();

    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
    const co = await memberRepo.findMember(t.org.id, t.userIds.admin);
    await memberRepo.updateMemberRole(t.org.id, co!.id, "owner");
    const owner = await memberRepo.findMember(t.org.id, t.userIds.owner);
    await memberService.removeMember({ ...t.actors.admin, role: "owner" }, { orgId: t.org.id, memberId: owner!.id });
    expect(await orgRepo.findPendingHandover(t.org.id)).toBeNull();
  });
});
